a=[list(map(int,l.split())) for l in src.splitlines()]; b=[list(map(int,l.split())) for l in out.splitlines()]; h,w=len(a),len(a[0]); pts=[(r,c) for r in range(h) for c in range(w) if a[r][c]==9]; actual={(r,c) for r in range(h) for c in range(w) if b[r][c]==3}
lines=[]; pred=set()
for i,(r,c) in enumerate(pts):
 for R,C in pts[i+1:]:
  dr,dc=R-r,C-c
  if dr==0 or dc==0 or abs(dr)==abs(dc):
   n=max(abs(dr),abs(dc)); cells={(r+(dr//n)*t,c+(dc//n)*t) for t in range(1,n)}
   cells={p for p in cells if a[p[0]][p[1]]==1}
   if cells:
    lines.append(((r,c),(R,C),cells & actual, cells-actual)); pred|=cells
print('pred',len(pred),'actual',len(actual),'miss',sorted(actual-pred),'extra',sorted(pred-actual)); print('lines contributing actual')
for x,y,hit,extra in lines:
 if hit: print(x,y,'hit',sorted(hit),'extra',sorted(extra))

